const printBudget = async (budgetId) => {
  if (!budgetId) {
    showError("Please provide a budget ID");
    return;
  }

  try {
    const budgetResponse = await axiosInstance.get(`budgets/${budgetId}`);
    const budget = budgetResponse.data;
    
    const projectResponse = await axiosInstance.get(`projects/${budget.project_id}`);
    const project = projectResponse.data;
    
    const items = budget.items || [];

    if (!Array.isArray(items)) {
      showError("Invalid budget items data");
