      <td>${i + 1}</td>
      <td>${card.id || 'N/A'}</td>
      <td>${card.date_created || 'N/A'}</td>
      <td>${card.service_type || '---'}${card.available_costnotes ? ' (' + card.available_costnotes + ')' : ''}</td>
      <td>${card.current_km_of_service || '---'}</td>
      <td>${card.next_km_of_service || '---'}</td>
      <td>${card.status?.name || 'N/A'}</td>
    </tr>
    `).join('')}
    ${jobCards.length > 10 ? `<tr><td colspan="7" class="text-center"><i>... and ${jobCards.length - 10} more job cards</i></td></tr>` : ''}
  </tbody>
</table>
` : ''}

<div style="margin-top: 30px; font-size: 10px; border-top: 1px solid #000; padding-top: 10px;">
  <p><strong>Report Generated:</strong> ${new Date().toLocaleString()}</p>
  <p><strong>Generated By:</strong> ${JSON.parse(localStorage.getItem('user')).name}</p>
</div>

</body>
</html>
`;

    const iframeDoc = iframe.contentWindow.document;
    iframeDoc.open();
    iframeDoc.write(printContent);
    iframeDoc.close();

    iframe.onload = () => {
      iframe.contentWindow.focus();
      iframe.contentWindow.print();
      setTimeout(() => {
        document.body.removeChild(iframe);
      }, 1000);
    };
  } catch (error) {
    showError(`Failed to print asset summary: ${error.message}`);
    console.error('Print asset summary error:', error);
  }
};

