  return `
  <div class="d-flex">
    <div class="ms-auto mx-5">
      <button 
        class="btn btn-primary rounded-circle p-2 d-flex justify-content-center align-items-center"
        ${callback && !status ? 'onclick="window.__refreshCallback__()"' : ''}
        title="Refresh page"
        style="width: 2.5rem; height: 2.5rem;"
        ${status ? 'disabled' : ''}
      >
        ${
          status 
